"""Writes midi_frames_golden.json: the wire bytes StagePilot 2.41.1 sent for lighting MIDI.

2.41.1 (backend/src/stagepilot/plugins/lights/client.py) builds
  mido.Message("note_on",  channel=channel - 1, note=note, velocity=velocity)
  mido.Message("note_off", channel=channel - 1, note=note, velocity=0)
and sends .bytes() over the port. This script does the same with mido 1.3.3 for every channel 1..16.

Regenerate:
  python3 -m venv /tmp/mv && /tmp/mv/bin/pip install mido==1.3.3
  /tmp/mv/bin/python crates/stagepilot-midi/tests/fixtures/generate_midi_golden.py \
      > crates/stagepilot-midi/tests/fixtures/midi_frames_golden.json
"""
import json

import mido

NOTES = [0, 60, 61, 72, 127]
VELOCITIES = [1, 64, 110, 127]

frames = []
for channel in range(1, 17):
    for note in NOTES:
        for velocity in VELOCITIES:
            on = mido.Message("note_on", channel=channel - 1, note=note, velocity=velocity)
            frames.append({"kind": "note_on", "channel": channel, "note": note, "velocity": velocity, "bytes": on.bytes()})
        off = mido.Message("note_off", channel=channel - 1, note=note, velocity=0)
        frames.append({"kind": "note_off", "channel": channel, "note": note, "velocity": 0, "bytes": off.bytes()})

print(json.dumps({
    "_comment": "Generated by generate_midi_golden.py with mido==1.3.3 (the library StagePilot 2.41.1 used). Do not edit by hand.",
    "mido": "1.3.3",
    "frames": frames,
}, indent=1))
